import{_ as t,o as n,c as i,a2 as a}from"./chunks/framework.e4u2V5E7.js";const g=JSON.parse('{"title":"Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability","description":"Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability","frontmatter":{"title":"Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability","description":"Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability"},"headers":[],"relativePath":"skills/workspace-optimization.md","filePath":"skills/workspace-optimization.md","lastUpdated":1784485118000}'),o={name:"skills/workspace-optimization.md"};function s(r,e,l,c,d,h){return n(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="strategies-for-identifying-weak-workspace-components-strengthening-content-merging-overlaps-and-improving-discoverability" tabindex="-1">Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability <a class="header-anchor" href="#strategies-for-identifying-weak-workspace-components-strengthening-content-merging-overlaps-and-improving-discoverability" aria-label="Permalink to &quot;Strategies for identifying weak workspace components, strengthening content, merging overlaps, and improving discoverability&quot;">​</a></h1><div class="tip custom-block" style="padding:1rem;"><strong>Skill:</strong> <code>workspace-optimization</code> | <strong>Category:</strong> workspace | <strong>Priority:</strong> medium | <strong>Level:</strong> concept </div><h1 id="workspace-optimization-skill" tabindex="-1">Workspace Optimization Skill <a class="header-anchor" href="#workspace-optimization-skill" aria-label="Permalink to &quot;Workspace Optimization Skill&quot;">​</a></h1><p>Practical guidance for analyzing, strengthening, and reorganizing an OpenCode workspace to maximize quality, discoverability, and engineering value.</p><hr><h2 id="identifying-weak-components" tabindex="-1">Identifying Weak Components <a class="header-anchor" href="#identifying-weak-components" aria-label="Permalink to &quot;Identifying Weak Components&quot;">​</a></h2><p>Weak components fail to deliver actionable value. Look for these signals:</p><h3 id="content-red-flags" tabindex="-1">Content Red Flags <a class="header-anchor" href="#content-red-flags" aria-label="Permalink to &quot;Content Red Flags&quot;">​</a></h3><ul><li><strong>Placeholder text</strong>: &quot;TODO&quot;, &quot;Coming soon&quot;, &quot;Add content here&quot;, &quot;TBD&quot;, &quot;[INSERT]&quot;</li><li><strong>Generic statements</strong>: &quot;Handle errors properly&quot;, &quot;Write good code&quot;, &quot;Follow best practices&quot; without specifics</li><li><strong>Missing examples</strong>: Components without at least one concrete example of usage</li><li><strong>Missing edge cases</strong>: No mention of error handling, boundary conditions, or failure modes</li><li><strong>Copy-paste artifacts</strong>: Sections that reference different projects, different naming conventions, or inconsistent terminology</li></ul><h3 id="structural-red-flags" tabindex="-1">Structural Red Flags <a class="header-anchor" href="#structural-red-flags" aria-label="Permalink to &quot;Structural Red Flags&quot;">​</a></h3><ul><li><strong>Single-section components</strong>: Only an overview with no actionable sections</li><li><strong>No cross-references</strong>: Not connected to any other component in the workspace</li><li><strong>Frontmatter-only components</strong>: Has metadata but no substantive body content</li><li><strong>Truncated content</strong>: Sections that end mid-thought or have incomplete sentences</li></ul><h3 id="detection-method" tabindex="-1">Detection Method <a class="header-anchor" href="#detection-method" aria-label="Permalink to &quot;Detection Method&quot;">​</a></h3><p>For each component, compute a weakness score:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>weakness = 0</span></span>
<span class="line"><span>if has_placeholder_text: weakness += 30</span></span>
<span class="line"><span>if no_examples: weakness += 20</span></span>
<span class="line"><span>if no_cross_references: weakness += 15</span></span>
<span class="line"><span>if line_count &lt; 30: weakness += 20</span></span>
<span class="line"><span>if sections_count &lt; 2: weakness += 15</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>Components with weakness score &gt;= 40 need attention.</p><hr><h2 id="strengthening-content-without-changing-meaning" tabindex="-1">Strengthening Content Without Changing Meaning <a class="header-anchor" href="#strengthening-content-without-changing-meaning" aria-label="Permalink to &quot;Strengthening Content Without Changing Meaning&quot;">​</a></h2><p>When improving a weak component, preserve the original intent while adding specificity.</p><h3 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h3><ol><li><strong>Expand, don&#39;t replace</strong>: Add detail to existing sections rather than rewriting them</li><li><strong>Be concrete</strong>: Turn &quot;handle errors&quot; into &quot;catch errors at API boundaries, log with context, return structured error responses&quot;</li><li><strong>Add examples</strong>: Every section should have at least one example showing the concept in action</li><li><strong>Reference related components</strong>: Add cross-links to skills, agents, or commands that complement this component</li><li><strong>Maintain voice</strong>: Match the existing writing style and terminology</li></ol><h3 id="strengthening-templates" tabindex="-1">Strengthening Templates <a class="header-anchor" href="#strengthening-templates" aria-label="Permalink to &quot;Strengthening Templates&quot;">​</a></h3><p><strong>For weak overview sections:</strong> Add: what this component does, when to use it, what it depends on, and what depends on it.</p><p><strong>For weak workflow sections:</strong> Add: numbered steps with specific tools/commands, expected inputs and outputs at each step, decision points and branching logic.</p><p><strong>For weak example sections:</strong> Add: a before/after showing the problem and solution, a code snippet or command showing exact usage, edge case handling.</p><p><strong>For weak reference sections:</strong> Add: links to related skills/agents/commands, external documentation URLs, related files in the workspace.</p><hr><h2 id="merging-overlapping-components" tabindex="-1">Merging Overlapping Components <a class="header-anchor" href="#merging-overlapping-components" aria-label="Permalink to &quot;Merging Overlapping Components&quot;">​</a></h2><p>When two components cover the same domain with significant overlap, consider merging.</p><h3 id="when-to-merge" tabindex="-1">When to Merge <a class="header-anchor" href="#when-to-merge" aria-label="Permalink to &quot;When to Merge&quot;">​</a></h3><ul><li>Both components address the same workflow from slightly different angles</li><li>Neither component is complete without the other</li><li>Users must frequently consult both to accomplish a task</li><li>Combined, they would form a single coherent guide</li></ul><h3 id="when-not-to-merge" tabindex="-1">When NOT to Merge <a class="header-anchor" href="#when-not-to-merge" aria-label="Permalink to &quot;When NOT to Merge&quot;">​</a></h3><ul><li>Components serve different audiences (beginner vs. advanced)</li><li>Components are in different categories (agent vs. skill) and serve structurally different purposes</li><li>One component is actively maintained and the other is legacy</li><li>Merging would create a component over 300 lines</li></ul><h3 id="merge-process" tabindex="-1">Merge Process <a class="header-anchor" href="#merge-process" aria-label="Permalink to &quot;Merge Process&quot;">​</a></h3><ol><li>Read both components fully</li><li>Identify unique content in each (content not present in the other)</li><li>Identify overlapping content (keep the better version of each overlap)</li><li>Determine the target structure (follow the richer component&#39;s structure)</li><li>Combine unique content into the target structure</li><li>Add cross-references from the absorbed component&#39;s former location</li><li>Update all references that pointed to the absorbed component</li></ol><hr><h2 id="improving-discoverability" tabindex="-1">Improving Discoverability <a class="header-anchor" href="#improving-discoverability" aria-label="Permalink to &quot;Improving Discoverability&quot;">​</a></h2><p>Components that exist but cannot be found are effectively useless.</p><h3 id="discoverability-checklist" tabindex="-1">Discoverability Checklist <a class="header-anchor" href="#discoverability-checklist" aria-label="Permalink to &quot;Discoverability Checklist&quot;">​</a></h3><ul><li><strong>Listed in AGENTS.md</strong>: Every agent and its routing rules should appear in the workspace manifest</li><li><strong>Listed in MANIFEST.md</strong>: Every skill, command, and playbook should appear in the relevant manifest section</li><li><strong>Referenced by at least one other component</strong>: Agents reference skills, commands reference agents, skills reference knowledge</li><li><strong>Consistent naming</strong>: File names match frontmatter names match manifest entries</li><li><strong>Tagged appropriately</strong>: Frontmatter includes category and tag fields for searchability</li><li><strong>Described clearly</strong>: Description field in frontmatter accurately conveys what the component does</li></ul><h3 id="discoverability-fixes" tabindex="-1">Discoverability Fixes <a class="header-anchor" href="#discoverability-fixes" aria-label="Permalink to &quot;Discoverability Fixes&quot;">​</a></h3><p>For orphaned components:</p><ol><li>Add a reference from the most relevant agent&#39;s routing rules</li><li>Add an entry to the appropriate MANIFEST.md section</li><li>Add cross-references from related components</li><li>Update AGENTS.md if the component represents a new capability</li></ol><p>For inconsistently named components:</p><ol><li>Standardize to lowercase-hyphen-separated for file names</li><li>Update all references to match the new name</li><li>Update manifest entries</li></ol><hr><h2 id="quality-thresholds" tabindex="-1">Quality Thresholds <a class="header-anchor" href="#quality-thresholds" aria-label="Permalink to &quot;Quality Thresholds&quot;">​</a></h2><p>Use these thresholds as benchmarks during analysis:</p><h3 id="content-depth" tabindex="-1">Content Depth <a class="header-anchor" href="#content-depth" aria-label="Permalink to &quot;Content Depth&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component Type</th><th>Minimum Lines</th><th>Ideal Lines</th><th>Maximum Lines</th></tr></thead><tbody><tr><td>Agent</td><td>50</td><td>100-200</td><td>300</td></tr><tr><td>Skill</td><td>40</td><td>80-150</td><td>250</td></tr><tr><td>Command</td><td>30</td><td>60-120</td><td>200</td></tr><tr><td>Playbook</td><td>50</td><td>100-200</td><td>300</td></tr><tr><td>Knowledge doc</td><td>30</td><td>60-150</td><td>250</td></tr></tbody></table><h3 id="metadata-completeness" tabindex="-1">Metadata Completeness <a class="header-anchor" href="#metadata-completeness" aria-label="Permalink to &quot;Metadata Completeness&quot;">​</a></h3><p>Every component must have at minimum:</p><ul><li>YAML frontmatter with <code>name</code> and <code>description</code></li><li>At least 2 section headings in the body</li><li>At least 1 example or reference</li></ul><h3 id="reference-health" tabindex="-1">Reference Health <a class="header-anchor" href="#reference-health" aria-label="Permalink to &quot;Reference Health&quot;">​</a></h3><ul><li>Every internal reference must resolve to an existing file</li><li>Every component should have at least 1 incoming reference from another component</li><li>No component should reference more than 10 other components (indicates over-coupling)</li></ul><h3 id="naming-consistency" tabindex="-1">Naming Consistency <a class="header-anchor" href="#naming-consistency" aria-label="Permalink to &quot;Naming Consistency&quot;">​</a></h3><ul><li>File names: lowercase, hyphen-separated, descriptive</li><li>Frontmatter name: matches file name (without extension)</li><li>Manifest entries: match frontmatter name exactly</li></ul><hr><h2 id="workspace-optimization-workflow" tabindex="-1">Workspace Optimization Workflow <a class="header-anchor" href="#workspace-optimization-workflow" aria-label="Permalink to &quot;Workspace Optimization Workflow&quot;">​</a></h2><p>When optimizing a workspace, follow this order:</p><ol><li><strong>Fix critical issues first</strong>: Broken references, missing files, security concerns</li><li><strong>Strengthen high-value components</strong>: Agents and skills used most frequently</li><li><strong>Merge clear duplicates</strong>: When overlap is unambiguous and merge is straightforward</li><li><strong>Add missing metadata</strong>: Low-risk, high-consistency improvement</li><li><strong>Improve discoverability</strong>: Cross-references, manifest entries, AGENTS.md updates</li><li><strong>Street weak content</strong>: Add examples, expand sections, improve specificity</li><li><strong>Clean up naming</strong>: Normalize file names and references</li></ol><p>Never skip from step 1 to step 6. Structural integrity before content quality.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><ul><li>File patterns match the skill&#39;s activation rules</li><li>Keywords in the conversation match the skill&#39;s domain</li><li>A related agent delegates to this skill</li></ul><h2 id="when-not-to-use" tabindex="-1">When NOT to Use <a class="header-anchor" href="#when-not-to-use" aria-label="Permalink to &quot;When NOT to Use&quot;">​</a></h2><ul><li>When the task falls outside this skill&#39;s domain</li><li>When a more specific skill exists for the task</li><li>When the skill&#39;s dependencies are not met</li></ul><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents that use this skill.</p><h2 id="related-skills" tabindex="-1">Related Skills <a class="header-anchor" href="#related-skills" aria-label="Permalink to &quot;Related Skills&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/skills/">Skills Registry</a> for related skills in the same cluster.</p><h2 id="customization-guide" tabindex="-1">Customization Guide <a class="header-anchor" href="#customization-guide" aria-label="Permalink to &quot;Customization Guide&quot;">​</a></h2><ol><li>Copy the skill to <code>.opencode/skills/</code> in your project</li><li>Modify the activation rules to match your project patterns</li><li>Add project-specific examples and templates</li><li>Update the related agents and skills references</li></ol><h2 id="extension-guide" tabindex="-1">Extension Guide <a class="header-anchor" href="#extension-guide" aria-label="Permalink to &quot;Extension Guide&quot;">​</a></h2><ol><li>Add new sections to the SKILL.md file</li><li>Include code examples for new patterns</li><li>Update anti-patterns with new findings</li><li>Maintain cross-references to related skills</li><li>Keep the skill focused on its core purpose</li></ol>`,73)])])}const m=t(o,[["render",s]]);export{g as __pageData,m as default};
